using Microsoft.EntityFrameworkCore; using SmartERP.Sales.DataAccess.Contexts; using SmartERP.Sales.Domain.Entities; using SmartERP.Sales.Domain.Enums; using SmartERP.Sales.Repositories.Interfaces;
namespace SmartERP.Sales.DataAccess.Repositories;
public sealed class SalesFinancialRecordRepository(SalesDbContext db):ISalesFinancialRecordRepository { public async Task<IReadOnlyList<SalesFinancialRecord>> ListAsync(int c,SalesFinancialRecordType t,CancellationToken token=default)=>await db.Records.AsNoTracking().Where(x=>x.CompanyId==c&&x.Type==t).OrderByDescending(x=>x.DocumentDateUtc??x.CreatedAtUtc).ToListAsync(token); public Task<SalesFinancialRecord?> FindAsync(int c,long id,CancellationToken token=default)=>db.Records.SingleOrDefaultAsync(x=>x.CompanyId==c&&x.Id==id,token); public Task<bool> CodeExistsAsync(int c,SalesFinancialRecordType t,string code,long? e=null,CancellationToken token=default)=>db.Records.AnyAsync(x=>x.CompanyId==c&&x.Type==t&&x.Code==code&&(!e.HasValue||x.Id!=e),token); public Task AddAsync(SalesFinancialRecord r,CancellationToken token=default)=>db.Records.AddAsync(r,token).AsTask(); public Task SaveChangesAsync(CancellationToken token=default)=>db.SaveChangesAsync(token); }
